import React, { useState, useRef } from 'react';
import './CreateInvitation.css';
import { GoogleMap, LoadScript, Marker, Autocomplete } from '@react-google-maps/api';
import couple1 from '../images/couple1.png';
import couple2 from '../images/couple2.png';
import couple3 from '../images/couple3.png';
import Modal_preview from './Modal_preview';

const defaultWeddingDetails = {
  brideName: '',
  groomName: '',
  weddingDate: '',
  weddingTime: '',
  weddingLocation: '',
  theme: 'classic',
  customText: 'Sizni to’yga bag’ishlangan bayramga taklif qilamiz.',
  selectedPhoto: couple1,
  locationCoords: null,
};

const mapLibraries = ['places'];

const CreateInvitation = () => {
  const [weddingDetails, setWeddingDetails] = useState(defaultWeddingDetails);
  const [modalOpen, setModalOpen] = useState(false);
  const autocompleteRef = useRef(null);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setWeddingDetails((prev) => ({ ...prev, [name]: value }));
  };

  const handlePlaceChanged = () => {
    const place = autocompleteRef.current.getPlace();
    if (place.geometry) {
      const lat = place.geometry.location.lat();
      const lng = place.geometry.location.lng();
      setWeddingDetails((prev) => ({
        ...prev,
        weddingLocation: place.formatted_address,
        locationCoords: { lat, lng },
      }));
    }
  };

  const handleSave = () => {
    const { brideName, groomName, weddingDate, weddingTime, weddingLocation, locationCoords } = weddingDetails;

    if (!brideName || !groomName || !weddingDate || !weddingTime || !weddingLocation || !locationCoords) {
      alert('Пожалуйста, заполните все обязательные поля, включая локацию.');
      return;
    }

    setModalOpen(true);
  };

  const closeModal = () => {
    setModalOpen(false);
  };

  return (
    <div className="invitation-container">
      <h1>Создание приглашения</h1>
      <form>
        <label htmlFor="brideName">Имя невесты:</label>
        <input
          type="text"
          id="brideName"
          name="brideName"
          value={weddingDetails.brideName}
          onChange={handleInputChange}
        />

        <label htmlFor="groomName">Имя жениха:</label>
        <input
          type="text"
          id="groomName"
          name="groomName"
          value={weddingDetails.groomName}
          onChange={handleInputChange}
        />

        <label htmlFor="weddingDate">Дата свадьбы:</label>
        <input
          type="date"
          id="weddingDate"
          name="weddingDate"
          value={weddingDetails.weddingDate}
          onChange={handleInputChange}
        />

        <label htmlFor="weddingTime">Время свадьбы:</label>
        <input
          type="time"
          id="weddingTime"
          name="weddingTime"
          value={weddingDetails.weddingTime}
          onChange={handleInputChange}
        />

        <label htmlFor="autocomplete">Место проведения:</label>
        <LoadScript googleMapsApiKey="ВАШ_API_КЛЮЧ" libraries={mapLibraries}>
          <Autocomplete onLoad={(ref) => (autocompleteRef.current = ref)} onPlaceChanged={handlePlaceChanged}>
            <input
              type="text"
              id="autocomplete"
              name="weddingLocation"
              placeholder="Введите место"
              value={weddingDetails.weddingLocation}
              readOnly
            />
          </Autocomplete>
        </LoadScript>

        <label>Выберите изображение:</label>
        <select
          name="selectedPhoto"
          value={weddingDetails.selectedPhoto}
          onChange={(e) => setWeddingDetails((prev) => ({ ...prev, selectedPhoto: e.target.value }))}
        >
          <option value={couple1}>Изображение 1</option>
          <option value={couple2}>Изображение 2</option>
          <option value={couple3}>Изображение 3</option>
        </select>
      </form>

      <button className="save-button" onClick={handleSave}>
        Сохранить и открыть приглашение
      </button>

      {modalOpen && (
        <Modal_preview isOpen={modalOpen} onClose={closeModal}>
          <h2>Превью приглашения</h2>
          <p>
            <strong>Невеста:</strong> {weddingDetails.brideName}
          </p>
          <p>
            <strong>Жених:</strong> {weddingDetails.groomName}
          </p>
          <p>
            <strong>Дата:</strong> {weddingDetails.weddingDate}
          </p>
          <p>
            <strong>Время:</strong> {weddingDetails.weddingTime}
          </p>
          <p>
            <strong>Место:</strong> {weddingDetails.weddingLocation}
          </p>

          {weddingDetails.locationCoords && (
            <LoadScript googleMapsApiKey="ВАШ_API_КЛЮЧ" libraries={mapLibraries}>
              <GoogleMap
                mapContainerStyle={{ width: '100%', height: '400px' }}
                center={weddingDetails.locationCoords}
                zoom={15}
              >
                <Marker position={weddingDetails.locationCoords} />
              </GoogleMap>
            </LoadScript>
          )}

          <button onClick={closeModal}>Закрыть</button>
        </Modal_preview>
      )}
    </div>
  );
};

export default CreateInvitation;
